fn is_non_prime(n: u64) -> bool {
    // Handle n = 2 separately (prime, so return false)
    if n == 2 {
        return false;
    }
    
    // Even numbers greater than 2 are composite
    if n % 2 == 0 {
        return true;
    }
    
    // Check odd divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    let mut k = 3;
    
    while k <= limit {
        if n % k == 0 {
            return true;
        }
        k += 2; // Only check odd numbers
    }
    
    false
}